// I forzieri negli slarghi: toccarli da' 'quanti' dell'oggetto (battaglia::OggettoId, fino al massimo che se
// ne porta), accende la bandiera (64-127) e fa dire il testo; preso, non torna.
struct Forziere
{
    int8_t area;                  // mondo::AreaId
    uint8_t tx;
    uint8_t ty;
    uint8_t bandiera;
    uint8_t oggetto;
    uint8_t quanti;
    testi::TestoId testo;
};

